# TODO: drop `n` in next major release
def autocurry(func, n=EMPTY, _spec=None, _args=(), _kwargs=None):
    """Creates a version of func returning its partial applications
       until sufficient arguments are passed."""
    spec = _spec or (get_spec(func) if n is EMPTY else (set(), n, n))
    required_names, required_n, max_n = spec

    # Get keyword-only argument info from signature
    kwonly_args = set()
    if not PY2 and hasattr(inspect, 'signature'):
        try:
            sig = inspect.signature(func)
            for param in sig.parameters.values():
                if param.kind == inspect.Parameter.KEYWORD_ONLY:
                    kwonly_args.add(param.name)
        except (ValueError, TypeError):
            pass

    def autocurried(*a, **kw):
        args = _args + a
        kwargs = (_kwargs or {}).copy()
        kwargs.update(kw)

        # Check if we have enough arguments to call
        # For keyword-only args, they don't count toward positional completion
        # unless explicitly provided

        # Count how many distinct parameters are covered
        pos_covered = len(args)
        kw_only_in_kwargs = set(kw.keys()) & kwonly_args
        total_covered = pos_covered + len(kw_only_in_kwargs)

        if total_covered >= max_n:
            return func(*args, **kwargs)
        elif pos_covered + len(set(kw.keys()) & required_names) >= required_n:
            # All required args covered, try calling
            try:
                return func(*args, **kwargs)
            except TypeError:
                # Not enough args, return partial
                return autocurry(func, _spec=spec, _args=args, _kwargs=kwargs)
        else:
            return autocurry(func, _spec=spec, _args=args, _kwargs=kwargs)

    return autocurried

